"""Lexer for jq language."""

KEYWORDS = {
    'if', 'then', 'else', 'elif', 'end',
    'as', 'def', 'reduce', 'foreach', 'try', 'catch',
    'import', 'include', 'module', 'and', 'or', 'not',
    'true', 'false', 'null', 'label',
}

class Token:
    __slots__ = ('type', 'value', 'pos', 'line', 'col')
    def __init__(self, type, value, pos=0, line=1, col=1):
        self.type = type
        self.value = value
        self.pos = pos
        self.line = line
        self.col = col
    def __repr__(self):
        return f"Token({self.type!r}, {self.value!r})"


class LexError(Exception):
    pass


class Lexer:
    def __init__(self, src):
        self.src = src
        self.pos = 0
        self.line = 1
        self.col = 1

    def error(self, msg):
        raise LexError(f"{msg} at line {self.line}, column {self.col}")

    def peek(self, off=0):
        p = self.pos + off
        if p < len(self.src):
            return self.src[p]
        return ''

    def advance(self):
        c = self.src[self.pos]
        self.pos += 1
        if c == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return c

    def skip_ws(self):
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c in ' \t\r\n':
                self.advance()
            elif c == '#':
                while self.pos < len(self.src) and self.src[self.pos] != '\n':
                    self.advance()
            else:
                break

    def read_string(self):
        """Read a string literal, returning list of parts.
        Each part is either ('str', text) or ('interp', tokens)."""
        assert self.src[self.pos] == '"'
        self.advance()
        parts = []
        cur = []
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c == '"':
                self.advance()
                if cur or not parts:
                    parts.append(('str', ''.join(cur)))
                return parts
            elif c == '\\':
                self.advance()
                if self.pos >= len(self.src):
                    self.error("unterminated string")
                e = self.advance()
                if e == 'n': cur.append('\n')
                elif e == 't': cur.append('\t')
                elif e == 'r': cur.append('\r')
                elif e == 'b': cur.append('\b')
                elif e == 'f': cur.append('\f')
                elif e == '\\': cur.append('\\')
                elif e == '/': cur.append('/')
                elif e == '"': cur.append('"')
                elif e == 'u':
                    hx = ''
                    for _ in range(4):
                        if self.pos >= len(self.src):
                            self.error("bad unicode escape")
                        hx += self.advance()
                    try:
                        codepoint = int(hx, 16)
                    except ValueError:
                        self.error("bad unicode escape")
                    # surrogate pair
                    if 0xD800 <= codepoint <= 0xDBFF:
                        if self.peek() == '\\' and self.peek(1) == 'u':
                            self.advance(); self.advance()
                            hx2 = ''
                            for _ in range(4):
                                if self.pos >= len(self.src):
                                    self.error("bad unicode escape")
                                hx2 += self.advance()
                            try:
                                low = int(hx2, 16)
                            except ValueError:
                                self.error("bad unicode escape")
                            codepoint = 0x10000 + (codepoint - 0xD800) * 0x400 + (low - 0xDC00)
                    cur.append(chr(codepoint))
                elif e == '(':
                    # interpolation
                    if cur or not parts:
                        parts.append(('str', ''.join(cur)))
                        cur = []
                    # read tokens until matching )
                    depth = 1
                    # tokenize by recursively using a sub-lexer
                    sub_start = self.pos
                    while self.pos < len(self.src) and depth > 0:
                        c2 = self.src[self.pos]
                        if c2 == '(':
                            depth += 1
                            self.advance()
                        elif c2 == ')':
                            depth -= 1
                            if depth == 0:
                                break
                            self.advance()
                        elif c2 == '"':
                            # read full string
                            self.read_string()
                        else:
                            self.advance()
                    if self.pos >= len(self.src):
                        self.error("unterminated interpolation")
                    inner = self.src[sub_start:self.pos]
                    self.advance()  # consume )
                    parts.append(('interp', inner))
                else:
                    self.error(f"bad escape \\{e}")
            else:
                cur.append(self.advance())
        self.error("unterminated string")

    def tokenize(self):
        tokens = []
        while True:
            self.skip_ws()
            if self.pos >= len(self.src):
                break
            start = self.pos
            line, col = self.line, self.col
            c = self.src[self.pos]
            if c == '"':
                parts = self.read_string()
                tokens.append(Token('STRING', parts, start, line, col))
                continue
            if c == '@':
                self.advance()
                name = ''
                while self.pos < len(self.src) and (self.src[self.pos].isalnum() or self.src[self.pos] == '_'):
                    name += self.advance()
                tokens.append(Token('FORMAT', name, start, line, col))
                continue
            if c == '$':
                self.advance()
                name = ''
                while self.pos < len(self.src) and (self.src[self.pos].isalnum() or self.src[self.pos] in '_:'):
                    name += self.advance()
                tokens.append(Token('VAR', name, start, line, col))
                continue
            if c.isdigit() or (c == '.' and self.pos + 1 < len(self.src) and self.src[self.pos+1].isdigit()):
                num = ''
                while self.pos < len(self.src) and self.src[self.pos].isdigit():
                    num += self.advance()
                if self.pos < len(self.src) and self.src[self.pos] == '.' and self.pos + 1 < len(self.src) and self.src[self.pos+1].isdigit():
                    num += self.advance()
                    while self.pos < len(self.src) and self.src[self.pos].isdigit():
                        num += self.advance()
                if self.pos < len(self.src) and self.src[self.pos] in 'eE':
                    num += self.advance()
                    if self.pos < len(self.src) and self.src[self.pos] in '+-':
                        num += self.advance()
                    while self.pos < len(self.src) and self.src[self.pos].isdigit():
                        num += self.advance()
                tokens.append(Token('NUMBER', num, start, line, col))
                continue
            if c.isalpha() or c == '_':
                ident = ''
                while self.pos < len(self.src) and (self.src[self.pos].isalnum() or self.src[self.pos] == '_' or self.src[self.pos] == ':'):
                    ident += self.advance()
                if ident in KEYWORDS:
                    tokens.append(Token(ident.upper(), ident, start, line, col))
                else:
                    tokens.append(Token('IDENT', ident, start, line, col))
                continue
            # operators / punctuation
            two = self.src[self.pos:self.pos+2]
            three = self.src[self.pos:self.pos+3]
            if three in ('//=',):
                self.advance(); self.advance(); self.advance()
                tokens.append(Token('ALTEQ', three, start, line, col))
                continue
            if two in ('==','!=','<=','>=','//','|=','+=','-=','*=','/=','%=','..','?/','//'):
                self.advance(); self.advance()
                if two == '==': tokens.append(Token('EQ', two, start, line, col))
                elif two == '!=': tokens.append(Token('NE', two, start, line, col))
                elif two == '<=': tokens.append(Token('LE', two, start, line, col))
                elif two == '>=': tokens.append(Token('GE', two, start, line, col))
                elif two == '//': tokens.append(Token('ALT', two, start, line, col))
                elif two == '|=': tokens.append(Token('UPDATE', two, start, line, col))
                elif two == '+=': tokens.append(Token('ADDEQ', two, start, line, col))
                elif two == '-=': tokens.append(Token('SUBEQ', two, start, line, col))
                elif two == '*=': tokens.append(Token('MULEQ', two, start, line, col))
                elif two == '/=': tokens.append(Token('DIVEQ', two, start, line, col))
                elif two == '%=': tokens.append(Token('MODEQ', two, start, line, col))
                elif two == '..': tokens.append(Token('RECURSE', two, start, line, col))
                elif two == '?/': tokens.append(Token('QSLASH', two, start, line, col))
                continue
            if c in '.,;:|+-*/%()[]{}=<>?':
                self.advance()
                simple = {
                    '.': 'DOT', ',': 'COMMA', ';': 'SEMI', ':': 'COLON',
                    '|': 'PIPE', '+': 'PLUS', '-': 'MINUS', '*': 'MUL',
                    '/': 'DIV', '%': 'MOD', '(': 'LPAREN', ')': 'RPAREN',
                    '[': 'LBRACK', ']': 'RBRACK', '{': 'LBRACE', '}': 'RBRACE',
                    '=': 'ASSIGN', '<': 'LT', '>': 'GT', '?': 'QUESTION',
                }
                tokens.append(Token(simple[c], c, start, line, col))
                continue
            self.error(f"Invalid character {c!r}")
        tokens.append(Token('EOF', None, self.pos, self.line, self.col))
        return tokens


def tokenize(src):
    return Lexer(src).tokenize()
