"""Lexer for jq language."""

KEYWORDS = {
    'if', 'then', 'else', 'elif', 'end',
    'as', 'def', 'reduce', 'foreach', 'try', 'catch',
    'import', 'include', 'module', 'and', 'or', 'not',
    'true', 'false', 'null', 'label',
}

class Token:
    __slots__ = ('type', 'value', 'pos', 'line', 'col')
    def __init__(self, type, value, pos=0, line=1, col=1):
        self.type = type
        self.value = value
        self.pos = pos
        self.line = line
        self.col = col
    def __repr__(self):
        return f"Token({self.type!r}, {self.value!r})"


class LexError(Exception):
    pass


class Lexer:
    def __init__(self, src):
        self.src = src
        self.pos = 0
        self.line = 1
        self.col = 1

    def error(self, msg):
        raise LexError(f"{msg} at line {self.line}, column {self.col}")

    def peek(self, off=0):
        p = self.pos + off
        if p < len(self.src):
            return self.src[p]
        return ''

    def advance(self):
        c = self.src[self.pos]
        self.pos += 1
        if c == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return c

    def skip_ws(self):
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c in ' \t\r\n':
                self.advance()
            elif c == '#':
                while self.pos < len(self.src) and self.src[self.pos] != '\n':
                    self.advance()
            else:
                break

    def read_string(self):
        """Read a string literal, returning list of parts.
        Each part is either ('str', text) or ('interp', tokens)."""
        assert self.src[self.pos] == '"'
        self.advance()
        parts = []
        cur = []
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c == '"':
                self.advance()
                if cur or not parts:
                    parts.append(('str', ''.join(cur)))
                return parts
            elif c == '\\':
                self.advance()
                if self.pos >= len(self.src):
                    self.error("unterminated string")
                e = self.advance()
                if e == 'n': cur.append('\n')
                elif e == 't': cur.append('\t')
                elif e == 'r': cur.append('\r')
                elif e == 'b': cur.append('\b')
                elif e == 'f': cur.append('\f')
                elif e == '\\': cur.append('\\')
                elif e == '/': cur.append('/')
                elif e == '"': cur.append('"')
                elif e == 'u':
                    hx = ''
                    for _ in range(4):
                        if self.pos >= len(self.src):
                            self.error("bad unicode escape")
                        hx += self.advance()
                    try:
                        codepoint = int(hx, 16)
                    except ValueError:
                        self.error("bad unicode escape")
                    # surrogate pair
                    if 0xD800 <= codepoint <= 0xDBFF:
                        if self.peek() == '\\' and self.peek(1) == 'u':
                            self.advance(); self.advance()
                            hx2 = ''
                            for _ in range(4):
                                if self.pos >= len(self.src):
                                    self.error("bad unicode escape")
                                hx2 += self.advance()
                            try:
                                low = int(hx2, 16)
                            except ValueError:
                                self.error("bad unicode escape")
                            codepoint = 0x10000 + (codepoint - 0xD800) * 0x400 + (low - 0xDC00)
                    cur.append(chr(codepoint))
                elif e == '(':
