                    sub_start = self.pos
                    while self.pos < len(self.src) and depth > 0:
                        c2 = self.src[self.pos]
                        if c2 == '(':
                            depth += 1
                            self.advance()
                        elif c2 == ')':
                            depth -= 1
                            if depth == 0:
                                break
                            self.advance()
                        elif c2 == '"':
