                            self.read_string()
                        else:
                            self.advance()
                    if self.pos >= len(self.src):
                        self.error("unterminated interpolation")
                    inner = self.src[sub_start:self.pos]
                    self.advance()  # consume )
                    parts.append(('interp', inner))
                else:
                    self.error(f"bad escape \\{e}")
            else:
                cur.append(self.advance())
        self.error("unterminated string")

