# ('assign', op, path_expr, value_expr)  op in '=', '|=', '+=', ...
# ('alt', a, b)
# ('var', name)
# ('as', expr, patterns, body)   patterns is list of PatternNode
# ('fcall', name, args)
# ('fdef', name, params, body, next)
# ('if', cond, then, elifs, else)
# ('try', body, catch)
# ('reduce', src, patterns, init, update)
# ('foreach', src, patterns, init, update, extract)
# ('array', body_or_None)
# ('object', entries)   entries = list of (key_node, value_node_or_None)
# ('string_interp', parts)  parts = list of ('str', text) / ('expr', ast)
# ('format', name)
# ('format_str', name, parts)  - @csv "...", etc.
# ('label', name, body)
# ('break', name)
# ('optional', expr)  - expr?
# ('recurse')   - ..


class Parser:
    def __init__(self, src):
        self.src = src
        self.tokens = tokenize(src)
        self.pos = 0

    def error(self, msg):
        t = self.tokens[self.pos] if self.pos < len(self.tokens) else None
        raise ParseError(f"{msg} at line {t.line if t else '?'}, column {t.col if t else '?'}")

    def peek(self, off=0):
        if self.pos + off < len(self.tokens):
            return self.tokens[self.pos + off]
        return self.tokens[-1]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def eat(self, type):
        t = self.peek()
        if t.type != type:
            self.error(f"expected {type} got {t.type}({t.value!r})")
        self.advance()
        return t

    def parse_program(self):
        node = self.parse_pipe()
        if self.peek().type != 'EOF':
            self.error(f"unexpected token {self.peek().type}")
        return node

    # grammar (simplified from actual jq):
    # pipe := comma ( '|' comma )*
    # comma := alt ( ',' alt )*
    # Actually jq parses 'as', 'reduce', 'if', etc at this level
    # Let's do: expr := pipe
    # pipe := commanode ('|' commanode)*
    # commanode := andor (',' andor)* -- actually alt/or
    # Full precedence (jq): | , // or and == != < > <= >= + - * / % unary_minus postfix
    # Assignments: = |= += -= *= /= //= %= - lowest precedence

    def parse_pipe(self):
        # handle def at start
        if self.peek().type == 'DEF':
            return self.parse_def()
        left = self.parse_comma()
        while self.peek().type == 'PIPE':
            self.advance()
            if self.peek().type == 'DEF':
                right = self.parse_def()
            else:
                right = self.parse_comma()
            left = ('pipe', left, right)
        return left

    def parse_def(self):
        self.eat('DEF')
        name = self.eat('IDENT').value
        params = []
        if self.peek().type == 'LPAREN':
            self.advance()
            while True:
                t = self.peek()
                if t.type == 'IDENT':
                    params.append(('filter', t.value))
                    self.advance()
                elif t.type == 'VAR':
                    params.append(('value', t.value))
                    self.advance()
                else:
                    self.error("expected parameter")
                if self.peek().type == 'SEMI':
                    self.advance()
                else:
                    break
            self.eat('RPAREN')
        self.eat('COLON')
        body = self.parse_pipe()
        self.eat('SEMI')
        # rest
        if self.peek().type == 'EOF' or self.peek().type in ('RPAREN', 'SEMI', 'RBRACK', 'RBRACE', 'COMMA', 'PIPE'):
            rest = ('lit', '__identity__')  # placeholder: actually jq doesn't allow def without body
            # actually in jq, def must be followed by a filter
            rest = ('ident_expr',)
        else:
            rest = self.parse_pipe()
        return ('fdef', name, params, body, rest)

    def parse_comma(self):
        left = self.parse_alt()
        while self.peek().type == 'COMMA':
            self.advance()
            right = self.parse_alt()
            left = ('comma', left, right)
        return left

    def parse_alt(self):
        # // (alt) has higher precedence than comma, lower than or
        left = self.parse_or()
        while self.peek().type == 'ALT':
            self.advance()
            right = self.parse_or()
            left = ('alt', left, right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.peek().type == 'OR':
            self.advance()
            right = self.parse_and()
            left = ('binop', 'or', left, right)
        return left

    def parse_and(self):
        left = self.parse_assign()
        while self.peek().type == 'AND':
            self.advance()
            right = self.parse_assign()
            left = ('binop', 'and', left, right)
        return left

    def parse_assign(self):
        # assignment is right-assoc, above and/or? actually in jq,
        # assignments have low precedence. Let me put them at this level
        left = self.parse_comparison()
        t = self.peek().type
        if t in ('ASSIGN', 'UPDATE', 'ADDEQ', 'SUBEQ', 'MULEQ', 'DIVEQ', 'MODEQ', 'ALTEQ'):
            op = self.advance().value
            right = self.parse_alt()  # right-assoc
            return ('assign', op, left, right)
        return left

    def parse_comparison(self):
        left = self.parse_additive()
        t = self.peek().type
        if t in ('EQ','NE','LT','GT','LE','GE'):
            op_map = {'EQ':'==','NE':'!=','LT':'<','GT':'>','LE':'<=','GE':'>='}
            op = op_map[t]
            self.advance()
            right = self.parse_additive()
            left = ('binop', op, left, right)
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.peek().type in ('PLUS','MINUS'):
            op = '+' if self.peek().type == 'PLUS' else '-'
            self.advance()
            right = self.parse_multiplicative()
            left = ('binop', op, left, right)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.peek().type in ('MUL','DIV','MOD'):
            t = self.peek().type
            op = {'MUL':'*','DIV':'/','MOD':'%'}[t]
            self.advance()
            right = self.parse_unary()
            left = ('binop', op, left, right)
        return left

    def parse_unary(self):
        if self.peek().type == 'MINUS':
            self.advance()
            return ('neg', self.parse_unary())
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            t = self.peek()
            if t.type == 'DOT':
                # could be .foo or .[...]
                # but only if next is an IDENT/STRING/LBRACK
                nxt = self.peek(1)
                if nxt.type == 'IDENT':
                    self.advance()
                    name = self.advance().value
                    optional = False
                    if self.peek().type == 'QUESTION':
                        self.advance()
                        optional = True
                    expr = ('field', expr, name, optional)
                elif nxt.type == 'STRING':
                    self.advance()
                    strparts = self.advance().value
                    # must be a simple string
                    if len(strparts) == 1 and strparts[0][0] == 'str':
                        name = strparts[0][1]
                    else:
                        self.error("string interpolation not allowed in field access")
                    optional = False
                    if self.peek().type == 'QUESTION':
                        self.advance()
                        optional = True
                    expr = ('field', expr, name, optional)
                elif nxt.type == 'LBRACK':
                    self.advance()
                    expr = self.parse_bracket(expr)
                else:
                    break
            elif t.type == 'LBRACK':
                expr = self.parse_bracket(expr)
            elif t.type == 'QUESTION':
                self.advance()
                expr = ('optional', expr)
            elif t.type == 'QSLASH':
                # ?//
                self.advance()
                right = self.parse_unary()
                expr = ('destruct_alt', expr, right)
            elif t.type == 'AS':
                self.advance()
                patterns = [self.parse_pattern()]
                while self.peek().type == 'QSLASH':
                    self.advance()
                    patterns.append(self.parse_pattern())
                self.eat('PIPE')
                body = self.parse_pipe()
                return ('as', expr, patterns, body)
            else:
                break
        return expr

    def parse_bracket(self, expr):
        self.eat('LBRACK')
        if self.peek().type == 'RBRACK':
            self.advance()
            optional = False
            if self.peek().type == 'QUESTION':
                self.advance()
                optional = True
            return ('iter', expr, optional)
        # parse optional from, :, optional to
        if self.peek().type == 'COLON':
            self.advance()
            to = self.parse_pipe()
            self.eat('RBRACK')
            optional = False
            if self.peek().type == 'QUESTION':
                self.advance(); optional = True
            return ('slice', expr, None, to, optional)
        first = self.parse_pipe()
        if self.peek().type == 'COLON':
            self.advance()
            if self.peek().type == 'RBRACK':
                self.eat('RBRACK')
                optional = False
                if self.peek().type == 'QUESTION':
                    self.advance(); optional = True
                return ('slice', expr, first, None, optional)
            to = self.parse_pipe()
            self.eat('RBRACK')
            optional = False
            if self.peek().type == 'QUESTION':
                self.advance(); optional = True
            return ('slice', expr, first, to, optional)
        self.eat('RBRACK')
        optional = False
        if self.peek().type == 'QUESTION':
            self.advance(); optional = True
        return ('index', expr, first, optional)

    def parse_pattern(self):
        t = self.peek()
        if t.type == 'VAR':
            self.advance()
            return ('pvar', t.value)
        if t.type == 'LBRACK':
            self.advance()
            items = []
            while self.peek().type != 'RBRACK':
                items.append(self.parse_pattern())
                if self.peek().type == 'COMMA':
                    self.advance()
                else:
                    break
            self.eat('RBRACK')
            return ('parr', items)
        if t.type == 'LBRACE':
            self.advance()
            items = []
            while self.peek().type != 'RBRACE':
                # key: pattern  OR $var  OR key (shorthand)
                if self.peek().type == 'VAR':
                    v = self.advance().value
                    items.append(('pkey', v, ('pvar', v)))
                elif self.peek().type in ('IDENT', 'STRING'):
                    if self.peek().type == 'IDENT':
                        key = self.advance().value
                    else:
                        parts = self.advance().value
                        if len(parts)==1 and parts[0][0]=='str':
                            key = parts[0][1]
                        else:
                            self.error("bad obj pattern key")
                    self.eat('COLON')
                    pat = self.parse_pattern()
                    items.append(('pkey', key, pat))
                elif self.peek().type == 'LPAREN':
                    self.advance()
                    key_expr = self.parse_pipe()
                    self.eat('RPAREN')
                    self.eat('COLON')
                    pat = self.parse_pattern()
                    items.append(('pkeyexpr', key_expr, pat))
                else:
                    self.error("bad obj pattern")
                if self.peek().type == 'COMMA':
                    self.advance()
                else:
                    break
            self.eat('RBRACE')
            return ('pobj', items)
        self.error("expected pattern")

    def parse_primary(self):
        t = self.peek()
        if t.type == 'NUMBER':
            self.advance()
            return ('lit_num', t.value)
        if t.type == 'TRUE':
            self.advance()
            return ('lit', True)
        if t.type == 'FALSE':
            self.advance()
            return ('lit', False)
        if t.type == 'NULL':
            self.advance()
            return ('lit', None)
        if t.type == 'STRING':
            self.advance()
            return ('string_interp', t.value)
        if t.type == 'FORMAT':
            self.advance()
            if self.peek().type == 'STRING':
                parts = self.advance().value
                return ('format_str', t.value, parts)
            return ('format', t.value)
        if t.type == 'VAR':
            self.advance()
            return ('var', t.value)
        if t.type == 'LPAREN':
            self.advance()
            node = self.parse_pipe()
            self.eat('RPAREN')
            return node
        if t.type == 'LBRACK':
            self.advance()
            if self.peek().type == 'RBRACK':
                self.advance()
                return ('array', None)
            body = self.parse_pipe()
            self.eat('RBRACK')
            return ('array', body)
        if t.type == 'LBRACE':
            self.advance()
            entries = []
            while self.peek().type != 'RBRACE':
                entries.append(self.parse_obj_entry())
                if self.peek().type == 'COMMA':
                    self.advance()
                else:
                    break
            self.eat('RBRACE')
            return ('object', entries)
        if t.type == 'DOT':
            self.advance()
            # plain '.'
            nxt = self.peek()
            if nxt.type == 'IDENT':
                name = self.advance().value
                optional = False
                if self.peek().type == 'QUESTION':
                    self.advance(); optional = True
                return ('field', ('ident_expr',), name, optional)
            if nxt.type == 'STRING':
                parts = self.advance().value
                if len(parts)==1 and parts[0][0]=='str':
                    name = parts[0][1]
                else:
                    self.error("string interpolation not allowed in field")
                optional = False
                if self.peek().type == 'QUESTION':
                    self.advance(); optional = True
                return ('field', ('ident_expr',), name, optional)
            if nxt.type == 'LBRACK':
                return self.parse_bracket(('ident_expr',))
            return ('ident_expr',)
        if t.type == 'RECURSE':
            self.advance()
            return ('fcall', 'recurse', [])
        if t.type == 'IF':
            return self.parse_if()
        if t.type == 'TRY':
            self.advance()
            body = self.parse_postfix()
            catch = None
            if self.peek().type == 'CATCH':
                self.advance()
                catch = self.parse_postfix()
            return ('try', body, catch)
        if t.type == 'REDUCE':
            self.advance()
            src = self.parse_postfix()
            self.eat('AS')
            pats = [self.parse_pattern()]
            self.eat('LPAREN')
            init = self.parse_pipe()
            self.eat('SEMI')
            upd = self.parse_pipe()
            self.eat('RPAREN')
            return ('reduce', src, pats, init, upd)
        if t.type == 'FOREACH':
            self.advance()
            src = self.parse_postfix()
            self.eat('AS')
            pats = [self.parse_pattern()]
            self.eat('LPAREN')
            init = self.parse_pipe()
            self.eat('SEMI')
            upd = self.parse_pipe()
            extract = ('ident_expr',)
            if self.peek().type == 'SEMI':
                self.advance()
                extract = self.parse_pipe()
            self.eat('RPAREN')
            return ('foreach', src, pats, init, upd, extract)
        if t.type == 'LABEL':
            self.advance()
            if self.peek().type != 'VAR':
                self.error("expected variable after label")
            name = self.advance().value
            self.eat('PIPE')
            body = self.parse_pipe()
            return ('label', name, body)
        if t.type == 'NOT':
            # 'not' as a postfix: parsed as identifier
            self.advance()
            return ('fcall', 'not', [])
        if t.type == 'IDENT':
            self.advance()
            args = []
            if self.peek().type == 'LPAREN':
                self.advance()
                args.append(self.parse_pipe())
                while self.peek().type == 'SEMI':
                    self.advance()
                    args.append(self.parse_pipe())
                self.eat('RPAREN')
            return ('fcall', t.value, args)
        self.error(f"unexpected {t.type}({t.value!r})")

    def parse_if(self):
        self.eat('IF')
        cond = self.parse_pipe()
        self.eat('THEN')
        then = self.parse_pipe()
        elifs = []
        while self.peek().type == 'ELIF':
            self.advance()
            c = self.parse_pipe()
            self.eat('THEN')
            b = self.parse_pipe()
            elifs.append((c, b))
        else_branch = None
        if self.peek().type == 'ELSE':
            self.advance()
            else_branch = self.parse_pipe()
        self.eat('END')
        return ('if', cond, then, elifs, else_branch)

    def parse_obj_entry(self):
        # key[: value]
        t = self.peek()
        if t.type == 'IDENT':
            self.advance()
            name = t.value
            key_node = ('lit', name)
            if self.peek().type == 'COLON':
                self.advance()
                val_node = self.parse_obj_value()
                return (key_node, val_node)
            else:
                # shorthand: key -> .key
                return (key_node, ('field', ('ident_expr',), name, False))
        if t.type == 'STRING':
            self.advance()
            parts = t.value
            if len(parts)==1 and parts[0][0]=='str':
                name = parts[0][1]
                key_node = ('lit', name)
            else:
                key_node = ('string_interp', parts)
            if self.peek().type == 'COLON':
                self.advance()
                val_node = self.parse_obj_value()
                return (key_node, val_node)
            else:
                # shorthand with string key - treat like field access? Only valid if simple
                if isinstance(key_node, tuple) and key_node[0]=='lit':
                    return (key_node, ('field', ('ident_expr',), key_node[1], False))
                return (key_node, ('string_interp', parts))
        if t.type == 'VAR':
            self.advance()
            name = t.value
            key_node = ('lit', name)
            if self.peek().type == 'COLON':
                self.advance()
                val_node = self.parse_obj_value()
                return (key_node, val_node)
            return (key_node, ('var', name))
        if t.type == 'LPAREN':
            self.advance()
            key_expr = self.parse_pipe()
            self.eat('RPAREN')
            self.eat('COLON')
            val_node = self.parse_obj_value()
            return (key_expr, val_node)
        # keywords as keys
        if t.type in ('TRUE', 'FALSE', 'NULL', 'IF', 'THEN', 'ELSE', 'ELIF', 'END',
                     'AND', 'OR', 'NOT', 'AS', 'DEF', 'REDUCE', 'FOREACH',
                     'TRY', 'CATCH', 'IMPORT', 'INCLUDE', 'MODULE', 'LABEL'):
            self.advance()
            name = t.value
            key_node = ('lit', name)
            if self.peek().type == 'COLON':
                self.advance()
                val_node = self.parse_obj_value()
                return (key_node, val_node)
            return (key_node, ('field', ('ident_expr',), name, False))
        if t.type == 'FORMAT':
            self.advance()
            name = t.value
            key_node = ('lit', name)
            if self.peek().type == 'COLON':
                self.advance()
                val_node = self.parse_obj_value()
                return (key_node, val_node)
            return (key_node, ('format', name))
        self.error(f"expected object key, got {t.type}")

    def parse_obj_value(self):
        # in obj value context, comma is not an operator, only pipe/alt
        return self.parse_alt()


def parse(src):
    return Parser(src).parse_program()
