"""JSON parsing and formatting compatible with jq output."""
import re


class JsonNumber:
    """Represents a JSON number preserving its original string representation."""
    __slots__ = ('s', '_v')
    def __init__(self, s):
        self.s = s if isinstance(s, str) else repr(s)
        self._v = None
    @property
    def v(self):
        if self._v is None:
            try:
                if '.' in self.s or 'e' in self.s or 'E' in self.s:
                    self._v = float(self.s)
                else:
                    self._v = int(self.s)
            except ValueError:
                self._v = float(self.s)
        return self._v


class JsonParseError(Exception):
    pass


def parse_stream(text):
    """Parse a stream of JSON values, yielding (value, next_pos)."""
    p = 0
    n = len(text)
