"""JSON parsing and formatting compatible with jq output."""
import re


class JsonNumber:
    """Represents a JSON number preserving its original string representation."""
    __slots__ = ('s', '_v')
    def __init__(self, s):
        self.s = s if isinstance(s, str) else repr(s)
        self._v = None
    @property
    def v(self):
        if self._v is None:
            try:
                if '.' in self.s or 'e' in self.s or 'E' in self.s:
                    self._v = float(self.s)
                else:
                    self._v = int(self.s)
            except ValueError:
                self._v = float(self.s)
        return self._v


class JsonParseError(Exception):
    pass


def parse_stream(text):
    """Parse a stream of JSON values, yielding (value, next_pos)."""
    p = 0
    n = len(text)
    while True:
        p = _skip_ws(text, p)
        if p >= n:
            break
        value, p = _parse_value(text, p)
        yield value
    return


def parse_all(text):
    return list(parse_stream(text))


def _skip_ws(text, p):
    n = len(text)
    while p < n and text[p] in ' \t\r\n':
        p += 1
    return p


def _parse_value(text, p):
    p = _skip_ws(text, p)
    if p >= len(text):
        raise JsonParseError(f"Invalid literal at line ?, column ?")
    c = text[p]
    if c == '{':
        return _parse_object(text, p)
    if c == '[':
        return _parse_array(text, p)
    if c == '"':
        return _parse_string(text, p)
    if c == 't':
        if text[p:p+4] == 'true':
            return True, p+4
        raise JsonParseError("Invalid literal")
    if c == 'f':
        if text[p:p+5] == 'false':
            return False, p+5
        raise JsonParseError("Invalid literal")
    if c == 'n':
        if text[p:p+4] == 'null':
            return None, p+4
        raise JsonParseError("Invalid literal")
    if c == '-' or c.isdigit():
        return _parse_number(text, p)
    raise JsonParseError(f"Invalid literal at position {p}")


def _parse_object(text, p):
    p += 1  # {
    result = {}
    p = _skip_ws(text, p)
    if p < len(text) and text[p] == '}':
        return result, p+1
    while True:
        p = _skip_ws(text, p)
        if p >= len(text) or text[p] != '"':
            raise JsonParseError("Expected string key")
        key, p = _parse_string(text, p)
        p = _skip_ws(text, p)
        if p >= len(text) or text[p] != ':':
            raise JsonParseError("Expected ':'")
        p += 1
        val, p = _parse_value(text, p)
        result[key] = val
        p = _skip_ws(text, p)
        if p < len(text) and text[p] == ',':
            p += 1
            continue
        if p < len(text) and text[p] == '}':
            return result, p+1
        raise JsonParseError("Expected ',' or '}'")


def _parse_array(text, p):
    p += 1
    result = []
    p = _skip_ws(text, p)
    if p < len(text) and text[p] == ']':
        return result, p+1
    while True:
        val, p = _parse_value(text, p)
        result.append(val)
        p = _skip_ws(text, p)
        if p < len(text) and text[p] == ',':
            p += 1
            continue
        if p < len(text) and text[p] == ']':
            return result, p+1
        raise JsonParseError("Expected ',' or ']'")


def _parse_string(text, p):
    assert text[p] == '"'
    p += 1
    out = []
    while p < len(text):
        c = text[p]
        if c == '"':
            return ''.join(out), p+1
        if c == '\\':
            p += 1
            if p >= len(text):
                raise JsonParseError("bad escape")
            e = text[p]; p += 1
            if e == 'n': out.append('\n')
            elif e == 't': out.append('\t')
            elif e == 'r': out.append('\r')
            elif e == 'b': out.append('\b')
            elif e == 'f': out.append('\f')
            elif e == '/': out.append('/')
            elif e == '\\': out.append('\\')
            elif e == '"': out.append('"')
            elif e == 'u':
                if p+4 > len(text):
                    raise JsonParseError("bad unicode")
                hx = text[p:p+4]; p += 4
                cp = int(hx, 16)
                if 0xD800 <= cp <= 0xDBFF and p+6 <= len(text) and text[p]=='\\' and text[p+1]=='u':
                    hx2 = text[p+2:p+6]
                    low = int(hx2, 16)
                    p += 6
                    cp = 0x10000 + (cp - 0xD800) * 0x400 + (low - 0xDC00)
                out.append(chr(cp))
            else:
                raise JsonParseError(f"bad escape \\{e}")
        elif ord(c) < 0x20:
            raise JsonParseError("invalid control char in string")
        else:
            out.append(c)
            p += 1
    raise JsonParseError("unterminated string")


_NUM_RE = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?')

def _parse_number(text, p):
    m = _NUM_RE.match(text, p)
    if not m:
        raise JsonParseError("bad number")
    s = m.group(0)
    return JsonNumber(s), m.end()


# ====== Formatting ======

def format_number(x):
    """Format a number for JSON output, matching jq."""
    if isinstance(x, JsonNumber):
        return _format_num_jq(x.s, x.v)
    if isinstance(x, bool):
        return 'true' if x else 'false'
    if isinstance(x, int):
        return str(x)
    if isinstance(x, float):
        return _format_float_jq(x)
    raise TypeError(f"not a number: {x!r}")


def _format_num_jq(orig_str, v):
    # If the original string is an integer, keep as is
    if isinstance(v, int):
        return str(v)
    # Float: use jq's format
    return _format_float_jq(v)


def _format_float_jq(x):
    """Format a float to match jq's output."""
    if x != x:  # NaN
        return 'null'
    if x == float('inf'):
        return '1.7976931348623157E308'
    if x == float('-inf'):
        return '-1.7976931348623157E308'
    if x == 0:
        # Preserve sign
        import math
        if math.copysign(1.0, x) < 0:
            return '-0'
        return '0'
    # Try to express as integer
    if x.is_integer() and abs(x) < 1e17:
        return str(int(x))
    # Use Python's repr and convert to jq's format
    # jq uses shortest round-trip representation with specific formatting
    s = repr(x)
    # Python produces e.g. '1.5', '0.0015', '1e+20', '1e-07'
    # jq uses 'E' (uppercase) for exponent
    if 'e' in s:
        mantissa, exp = s.split('e')
        exp = int(exp)
        # jq format: 1E+10 with uppercase E and always a sign
        if exp >= 0:
            sign = '+'
        else:
            sign = '-'
            exp = -exp
        # Mantissa - strip trailing zeros and trailing '.'?
        # python repr of 1e10 is '10000000000.0' for small exponents
        # but for 1e20 it's '1e+20'
        if '.' in mantissa:
            # normalize
            pass
        return f"{mantissa}E{sign}{exp}"
    return s


def format_string(s, ascii_only=False):
    out = ['"']
    i = 0
    while i < len(s):
        c = s[i]
        o = ord(c)
        if c == '"':
            out.append('\\"')
        elif c == '\\':
            out.append('\\\\')
        elif c == '\n':
            out.append('\\n')
        elif c == '\r':
            out.append('\\r')
        elif c == '\t':
            out.append('\\t')
        elif c == '\b':
            out.append('\\b')
        elif c == '\f':
            out.append('\\f')
        elif o < 0x20 or o == 0x7f:
            out.append(f'\\u{o:04x}')
        elif ascii_only and o > 0x7e:
            if o > 0xFFFF:
                # encode as surrogate pair
                cp = o - 0x10000
                hi = 0xD800 + (cp >> 10)
                lo = 0xDC00 + (cp & 0x3FF)
                out.append(f'\\u{hi:04x}\\u{lo:04x}')
            else:
                out.append(f'\\u{o:04x}')
        else:
            out.append(c)
        i += 1
    out.append('"')
    return ''.join(out)


def format_value(v, indent=2, sort_keys=False, ascii_only=False, tab=False, _depth=0):
    """Format a JSON value using jq conventions.
    indent: number of spaces, 0 = compact, -1 = tab
