            parts = [format_value(x, indent, sort_keys, ascii_only, tab, _depth+1) for x in v]
            return '[' + ','.join(parts) + ']'
        pad = '\t' if tab else (' ' * indent)
        inner_pad = pad * (_depth + 1)
        outer_pad = pad * _depth
        parts = [inner_pad + format_value(x, indent, sort_keys, ascii_only, tab, _depth+1) for x in v]
        return '[\n' + ',\n'.join(parts) + '\n' + outer_pad + ']'
    if isinstance(v, dict):
        if not v:
            return '{}'
        items = list(v.items())
        if sort_keys:
            items.sort(key=lambda kv: kv[0])
        if indent == 0:
            parts = [format_string(k, ascii_only) + ':' + format_value(val, indent, sort_keys, ascii_only, tab, _depth+1) for k, val in items]
            return '{' + ','.join(parts) + '}'
