def jq_sub(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        return _wrap_num(_num(a) - _num(b))
    if ta == 'array' and tb == 'array':
        return [x for x in a if not any(jq_equal(x, y) for y in b)]
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be subtracted")


def jq_mul(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        return _wrap_num(_num(a) * _num(b))
    if ta == 'string' and tb == 'string':
