        if nb == 0:
            raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be divided because the divisor is zero")
        na = _num(a)
        if isinstance(na, int) and isinstance(nb, int) and na % nb == 0:
