    if kind == 'slice':
        _, sub, fr, to, optional = node
        for p in eval_paths(sub, value, env):
            sub_val = resolve_path(value, p)
            fr_iter = eval_filter(fr, value, env) if fr else [None]
            for frv in fr_iter:
                to_iter = eval_filter(to, value, env) if to else [None]
                for tov in to_iter:
