def set_path(v, path, new_val):
    """Return a new copy of v with path set to new_val."""
    if not path:
        return new_val
    p = path[0]
    rest = path[1:]
    if isinstance(p, str):
        if v is None:
            v = {}
        if not isinstance(v, dict):
            raise JqError(f"Cannot update {jq_typeof(v)} with key")
        cur = v.get(p)
        new_sub = set_path(cur, rest, new_val)
        r = dict(v)
        r[p] = new_sub
        return r
    if isinstance(p, int):
        if v is None:
            v = []
        if not isinstance(v, list):
            raise JqError(f"Cannot update {jq_typeof(v)} with index")
        L = len(v)
        idx = p
        if idx < 0:
            idx += L
        if idx < 0:
            raise JqError("Out of range negative index")
        r = list(v)
        while len(r) <= idx:
            r.append(None)
        r[idx] = set_path(r[idx] if idx < L else None, rest, new_val)
        return r
    if isinstance(p, dict):
        fi = p.get('start'); ti = p.get('end')
        if v is None:
            v = []
        if not isinstance(v, list):
            raise JqError(f"Cannot slice {jq_typeof(v)}")
        L = len(v)
        fi2 = 0 if fi is None else int(_num(fi))
        ti2 = L if ti is None else int(_num(ti))
        if fi2 < 0: fi2 = max(0, L+fi2)
        if ti2 < 0: ti2 = max(0, L+ti2)
        fi2 = max(0, min(L, fi2))
        ti2 = max(0, min(L, ti2))
        slice_val = v[fi2:ti2]
        new_sub = set_path(slice_val, rest, new_val)
        if not isinstance(new_sub, list):
            raise JqError("slice must be replaced with an array")
        return v[:fi2] + new_sub + v[ti2:]
    raise JqError("bad path element")


