    if not path:
        return None
    p = path[0]
    rest = path[1:]
    if isinstance(p, str):
        if v is None:
            return None
        if not isinstance(v, dict):
            raise JqError(f"Cannot delete from {jq_typeof(v)}")
        if p not in v:
            return v
        if not rest:
            r = dict(v)
            del r[p]
            return r
        r = dict(v)
        r[p] = del_path(r[p], rest)
        return r
    if isinstance(p, int):
        if v is None: return None
        if not isinstance(v, list):
            raise JqError("Cannot delete from non-array")
        L = len(v)
        idx = p
        if idx < 0: idx += L
        if idx < 0 or idx >= L:
            return v
        if not rest:
            return v[:idx] + v[idx+1:]
        r = list(v)
        r[idx] = del_path(r[idx], rest)
        return r
    if isinstance(p, dict):
        # slice delete
        if not rest:
            L = len(v)
            fi = p.get('start'); ti = p.get('end')
            fi2 = 0 if fi is None else int(_num(fi))
            ti2 = L if ti is None else int(_num(ti))
            if fi2 < 0: fi2 = max(0, L+fi2)
            if ti2 < 0: ti2 = max(0, L+ti2)
            fi2 = max(0, min(L, fi2))
            ti2 = max(0, min(L, ti2))
            return v[:fi2] + v[ti2:]
        # recurse inside slice - complex, skip
        return v
    return v


def eval_assign(op, path_expr, val_expr, value, env):
    if op == '=':
        # Get all the new values first; for each, set the paths
        for nv in eval_filter(val_expr, value, env):
            r = value
            for p in eval_paths(path_expr, value, env):
                r = set_path(r, p, nv)
            yield r
        return
    if op == '|=':
        # For each path, apply the update
        r = value
        for p in eval_paths(path_expr, value, env):
            cur = resolve_path(r, p)
            results = list(eval_filter(val_expr, cur, env))
            if not results:
                # delete
                r = del_path(r, p)
            else:
                r = set_path(r, p, results[0])
        yield r
        return
    op_map = {'+=':'+', '-=':'-', '*=':'*', '/=':'/', '%=':'%'}
    if op in op_map:
        bop = op_map[op]
        for nv in eval_filter(val_expr, value, env):
            r = value
            for p in eval_paths(path_expr, value, env):
                cur = resolve_path(r, p)
                new_val = apply_binop(bop, cur, nv)
                r = set_path(r, p, new_val)
            yield r
        return
    if op == '//=':
        r = value
        for p in eval_paths(path_expr, value, env):
            cur = resolve_path(r, p)
            if cur is not None and cur is not False:
                continue
            for nv in eval_filter(val_expr, value, env):
                r = set_path(r, p, nv)
                break
