            yield []
            return
        yield list(eval_filter(body, value, env))
        return
    if kind == 'object':
        yield from eval_object(node[1], value, env)
        return
    if kind == 'if':
        _, cond, then, elifs, else_br = node
        yield from eval_if(cond, then, elifs, else_br, value, env)
        return
    if kind == 'try':
        _, body, catch = node
        try:
            yield from eval_filter(body, value, env)
        except JqError as e:
            if catch is None:
                return
            err_val = e.value if e.value is not None else e.msg
            yield from eval_filter(catch, err_val, env)
        return
    if kind == 'reduce':
        _, src, pats, init, upd = node
        acc_list = list(eval_filter(init, value, env))
        for acc in acc_list:
            cur = acc
            for sv in eval_filter(src, value, env):
                new_env = env.child()
                bind_patterns(pats, sv, new_env)
                results = list(eval_filter(upd, cur, new_env))
                if results:
                    cur = results[-1]
            yield cur
        return
    if kind == 'foreach':
        _, src, pats, init, upd, extract = node
        for acc in eval_filter(init, value, env):
            cur = acc
            for sv in eval_filter(src, value, env):
                new_env = env.child()
                bind_patterns(pats, sv, new_env)
                for newcur in eval_filter(upd, cur, new_env):
                    cur = newcur
                    yield from eval_filter(extract, cur, new_env)
        return
    if kind == 'as':
        _, src_expr, patterns, body = node
        for sv in eval_filter(src_expr, value, env):
            bound = False
            last_err = None
            for i, pat in enumerate(patterns):
                try:
                    new_env = env.child()
                    bind_patterns([pat], sv, new_env)
                    yield from eval_filter(body, value, new_env)
                    bound = True
                    break
                except JqError as e:
                    last_err = e
                    if i == len(patterns) - 1:
                        raise
            if not bound and last_err:
                raise last_err
        return
    if kind == 'assign':
        _, op, path_expr, val_expr = node
        yield from eval_assign(op, path_expr, val_expr, value, env)
        return
    if kind == 'fdef':
        _, name, params, body, rest = node
        new_env = env.child()
        key = (name, len(params))
        new_env.funcs[key] = (params, body, new_env)
        yield from eval_filter(rest, value, new_env)
        return
    if kind == 'fcall':
        _, name, args = node
        yield from eval_fcall(name, args, value, env)
        return
    if kind == 'label':
        _, name, body = node
        try:
            yield from eval_filter(body, value, env)
        except JqBreak as b:
            if b.label != name:
                raise
        return
    raise JqError(f"unimplemented: {kind}")


def eval_string_interp(parts, value, env):
    # parts: list of ('str', text) or ('interp', inner_src)
    # interp means we need to eval the inner expression and format result
    from .jq_parser import parse
    # Pre-parse interpolations
    items = []
    for kind, text in parts:
        if kind == 'str':
            items.append((kind, text))
        else:
            items.append(('expr', parse(text)))
    yield from _concat_interp(items, 0, '', value, env)


def _concat_interp(items, idx, acc, value, env):
    if idx >= len(items):
        yield acc
        return
    kind, it = items[idx]
    if kind == 'str':
        yield from _concat_interp(items, idx+1, acc + it, value, env)
        return
    # expr
    for v in eval_filter(it, value, env):
        if isinstance(v, str):
            s = v
        else:
            s = format_value(v, indent=0)
        yield from _concat_interp(items, idx+1, acc + s, value, env)


def eval_format_str(fmt_name, parts, value, env):
    # For @format "...", each interpolation is formatted using the format
    from .jq_parser import parse
    items = []
    for kind, text in parts:
        if kind == 'str':
            items.append(('str', text))
        else:
            items.append(('expr', parse(text)))
    yield from _concat_fmt(items, 0, '', fmt_name, value, env)


def _concat_fmt(items, idx, acc, fmt_name, value, env):
    if idx >= len(items):
        yield acc
        return
    kind, it = items[idx]
    if kind == 'str':
        yield from _concat_fmt(items, idx+1, acc + it, fmt_name, value, env)
        return
    for v in eval_filter(it, value, env):
        s = apply_format(fmt_name, v)
        yield from _concat_fmt(items, idx+1, acc + s, fmt_name, value, env)


def apply_format(name, v):
    if name == 'text':
        if isinstance(v, str): return v
        return format_value(v, indent=0)
    if name == 'json':
        return format_value(v, indent=0)
    if name == 'html':
        if not isinstance(v, str):
            s = format_value(v, indent=0)
        else:
            s = v
        return (s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
                .replace("'",'&#39;').replace('"','&quot;'))
    if name == 'uri':
        if not isinstance(v, str):
            s = format_value(v, indent=0)
        else:
            s = v
        out = []
        for c in s.encode('utf-8'):
            if chr(c) in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~":
                out.append(chr(c))
            else:
                out.append(f"%{c:02X}")
        return ''.join(out)
    if name == 'csv' or name == 'tsv':
        if not isinstance(v, list):
            raise JqError(f"{jq_typeof(v)} ({jq_repr(v)}) cannot be csv-formatted, only array")
        sep = ',' if name == 'csv' else '\t'
        parts = []
        for x in v:
            if x is None:
                parts.append('')
            elif isinstance(x, bool):
                parts.append('true' if x else 'false')
            elif isinstance(x, (int, float, JsonNumber)):
                parts.append(format_value(x, indent=0))
            elif isinstance(x, str):
                if name == 'csv':
                    parts.append('"' + x.replace('"','""') + '"')
                else:
                    parts.append(x.replace('\\','\\\\').replace('\t','\\t').replace('\r','\\r').replace('\n','\\n'))
            else:
                raise JqError(f"{jq_typeof(x)} is not valid in a csv row")
        return sep.join(parts)
    if name == 'sh':
        def sh_q(x):
            if isinstance(x, str):
                return "'" + x.replace("'", "'\\''") + "'"
            return format_value(x, indent=0)
        if isinstance(v, list):
            return ' '.join(sh_q(x) for x in v)
        return sh_q(v)
    if name == 'base32':
        import base64
        if not isinstance(v, str):
            raise JqError(f"{jq_typeof(v)} cannot be base32-encoded")
        return base64.b32encode(v.encode('utf-8')).decode('ascii')
    if name == 'base32d':
        import base64
        if not isinstance(v, str):
            raise JqError(f"{jq_typeof(v)} cannot be base32-decoded")
        return base64.b32decode(v).decode('utf-8')
    if name == 'base64':
        import base64
        if not isinstance(v, str):
            raise JqError(f"{jq_typeof(v)} cannot be base64-encoded")
        return base64.b64encode(v.encode('utf-8')).decode('ascii')
    if name == 'base64d':
        import base64
        if not isinstance(v, str):
            raise JqError(f"{jq_typeof(v)} cannot be base64-decoded")
        return base64.b64decode(v).decode('utf-8')
    raise JqError(f"@{name} is not a known format")


def eval_object(entries, value, env):
    # Iterative cross-product construction
    def rec(i, cur):
        if i >= len(entries):
            yield dict(cur)
            return
        key_node, val_node = entries[i]
        for k in eval_filter(key_node, value, env):
            if not isinstance(k, str):
                raise JqError(f"object key must be a string, not {jq_typeof(k)}")
            for v in eval_filter(val_node, value, env):
                cur.append((k, v))
                yield from rec(i+1, cur)
                cur.pop()
    # Python dicts preserve insertion order
    yield from rec(0, [])


def eval_if(cond, then, elifs, else_br, value, env):
    for c in eval_filter(cond, value, env):
        if jq_truthy(c):
            yield from eval_filter(then, value, env)
        else:
            # try elifs
            matched = False
            for ec, eb in elifs:
                ok = False
                for cc in eval_filter(ec, value, env):
                    if jq_truthy(cc):
                        ok = True
                        yield from eval_filter(eb, value, env)
                if ok:
                    matched = True
                    break
            if not matched:
                if else_br is not None:
                    yield from eval_filter(else_br, value, env)
                else:
                    yield value


def bind_patterns(patterns, value, env):
    # All patterns bind from the same value
    for pat in patterns:
        bind_pattern(pat, value, env)


def bind_pattern(pat, value, env):
    kind = pat[0]
    if kind == 'pvar':
        env.vars[pat[1]] = value
        return
    if kind == 'parr':
        if not isinstance(value, list):
            if value is None:
                value = []
            else:
                raise JqError(f"cannot destructure {jq_typeof(value)} as array")
        for i, subpat in enumerate(pat[1]):
            v = value[i] if i < len(value) else None
            bind_pattern(subpat, v, env)
        return
    if kind == 'pobj':
        if not isinstance(value, dict):
            if value is None:
                value = {}
            else:
                raise JqError(f"cannot destructure {jq_typeof(value)} as object")
        for item in pat[1]:
            if item[0] == 'pkey':
                k = item[1]
                bind_pattern(item[2], value.get(k), env)
            elif item[0] == 'pkeyexpr':
                for k in eval_filter(item[1], value, env):
                    if not isinstance(k, str):
                        raise JqError("object pattern key must be string")
                    bind_pattern(item[2], value.get(k), env)
        return
    raise JqError(f"unknown pattern {kind}")


# ============ Accessors ============
def get_field(v, name):
    if v is None:
        return None
    if isinstance(v, dict):
        return v.get(name)
    raise JqError(f"Cannot index {jq_typeof(v)} with \"{name}\"")


def get_index(v, idx):
    if v is None:
        return None
    if isinstance(v, list):
        if not isinstance(idx, (int, float, JsonNumber)) or isinstance(idx, bool):
            raise JqError(f"Cannot index array with {jq_typeof(idx)} \"{idx}\"")
        i = int(_num(idx))
        if i < 0:
            i += len(v)
        if 0 <= i < len(v):
            return v[i]
        return None
    if isinstance(v, dict):
        if not isinstance(idx, str):
            raise JqError(f"Cannot index object with {jq_typeof(idx)}")
        return v.get(idx)
    raise JqError(f"Cannot index {jq_typeof(v)} with {jq_typeof(idx)}")


def get_slice(v, fr, to):
    if v is None:
        return None
    if fr is not None and not isinstance(fr, (int, float, JsonNumber)):
        raise JqError("Slice indices must be numbers")
    if to is not None and not isinstance(to, (int, float, JsonNumber)):
        raise JqError("Slice indices must be numbers")
    if isinstance(v, list):
        L = len(v)
        fi = 0 if fr is None else int(_num(fr))
        ti = L if to is None else int(_num(to))
        if fi < 0: fi = max(0, L + fi)
        if ti < 0: ti = max(0, L + ti)
        fi = max(0, min(L, fi))
        ti = max(0, min(L, ti))
        if ti < fi: ti = fi
        return v[fi:ti]
    if isinstance(v, str):
        L = len(v)
        fi = 0 if fr is None else int(_num(fr))
        ti = L if to is None else int(_num(to))
        if fi < 0: fi = max(0, L + fi)
        if ti < 0: ti = max(0, L + ti)
        fi = max(0, min(L, fi))
        ti = max(0, min(L, ti))
        if ti < fi: ti = fi
        return v[fi:ti]
    raise JqError(f"Cannot slice {jq_typeof(v)}")


# ============ Binops ============
def apply_binop(op, a, b):
    if op == '+':
        return jq_add(a, b)
    if op == '-':
        return jq_sub(a, b)
    if op == '*':
        return jq_mul(a, b)
    if op == '/':
        return jq_div(a, b)
    if op == '%':
        return jq_mod(a, b)
    if op == '==': return jq_equal(a, b)
    if op == '!=': return not jq_equal(a, b)
    if op == '<': return jq_compare(a, b) < 0
    if op == '<=': return jq_compare(a, b) <= 0
    if op == '>': return jq_compare(a, b) > 0
    if op == '>=': return jq_compare(a, b) >= 0
    raise JqError(f"unknown binop {op}")


def jq_add(a, b):
    if a is None: return b
    if b is None: return a
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        return _wrap_num(_num(a) + _num(b))
    if ta == 'string' and tb == 'string':
        return a + b
    if ta == 'array' and tb == 'array':
        return a + b
    if ta == 'object' and tb == 'object':
        r = dict(a)
        r.update(b)
        return r
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be added")


def jq_sub(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        return _wrap_num(_num(a) - _num(b))
    if ta == 'array' and tb == 'array':
        return [x for x in a if not any(jq_equal(x, y) for y in b)]
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be subtracted")


def jq_mul(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        return _wrap_num(_num(a) * _num(b))
    if ta == 'string' and tb == 'string':
        # split a by b (jq: "a,b,c" * "," returns ["a","b","c"])
        return a.split(b) if b else None
    if ta == 'null' or tb == 'null':
        return None
    if ta == 'string' and tb == 'number':
        n = int(_num(b))
        if n <= 0: return None
        return a * n
    if ta == 'object' and tb == 'object':
        return _deep_merge(a, b)
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be multiplied")


def _deep_merge(a, b):
    r = dict(a)
    for k, v in b.items():
        if k in r and isinstance(r[k], dict) and isinstance(v, dict):
            r[k] = _deep_merge(r[k], v)
        else:
            r[k] = v
    return r


def jq_div(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        nb = _num(b)
        if nb == 0:
            raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be divided because the divisor is zero")
        na = _num(a)
        if isinstance(na, int) and isinstance(nb, int) and na % nb == 0:
            return na // nb
        return _wrap_num(na / nb)
    if ta == 'string' and tb == 'string':
        if not b:
            # jq splits into characters
            return list(a)
        return a.split(b)
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be divided")


def jq_mod(a, b):
    ta, tb = jq_typeof(a), jq_typeof(b)
    if ta == 'number' and tb == 'number':
        na = int(_num(a))
        nb = int(_num(b))
        if nb == 0:
            raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be divided (modulo) because the divisor is zero")
        # jq uses C-style modulo
        r = abs(na) % abs(nb)
        if na < 0: r = -r
        return r
    raise JqError(f"{ta} ({jq_repr(a)}) and {tb} ({jq_repr(b)}) cannot be divided")


# ============ Paths & Assignments ============
def eval_paths(node, value, env):
    """Yield list-of-path-components for each location this filter addresses."""
    kind = node[0]
    if kind == 'ident_expr':
        yield []
        return
    if kind == 'pipe':
        a, b = node[1], node[2]
        for p in eval_paths(a, value, env):
            sub = resolve_path(value, p)
            for q in eval_paths(b, sub, env):
                yield p + q
        return
    if kind == 'comma':
        yield from eval_paths(node[1], value, env)
        yield from eval_paths(node[2], value, env)
        return
    if kind == 'field':
        _, sub, name, optional = node
        for p in eval_paths(sub, value, env):
            sub_val = resolve_path(value, p)
            if sub_val is None or isinstance(sub_val, dict):
                yield p + [name]
            else:
                if optional:
                    continue
                raise JqError(f"Cannot index {jq_typeof(sub_val)} with \"{name}\"")
        return
    if kind == 'index':
        _, sub, idx_node, optional = node
        for p in eval_paths(sub, value, env):
            sub_val = resolve_path(value, p)
            for idx in eval_filter(idx_node, value, env):
                if isinstance(idx, str) and (sub_val is None or isinstance(sub_val, dict)):
                    yield p + [idx]
                elif isinstance(idx, (int, float, JsonNumber)) and (sub_val is None or isinstance(sub_val, list)):
                    yield p + [int(_num(idx))]
                else:
                    if optional: continue
                    raise JqError(f"Cannot index {jq_typeof(sub_val)} with {jq_typeof(idx)}")
        return
    if kind == 'iter':
        _, sub, optional = node
        for p in eval_paths(sub, value, env):
            sub_val = resolve_path(value, p)
            if isinstance(sub_val, list):
                for i in range(len(sub_val)):
                    yield p + [i]
            elif isinstance(sub_val, dict):
                for k in sub_val.keys():
                    yield p + [k]
            elif sub_val is None:
                pass
            else:
                if optional: continue
                raise JqError(f"Cannot iterate over {jq_typeof(sub_val)}")
        return
    if kind == 'slice':
        _, sub, fr, to, optional = node
        for p in eval_paths(sub, value, env):
            sub_val = resolve_path(value, p)
            fr_iter = eval_filter(fr, value, env) if fr else [None]
            for frv in fr_iter:
                to_iter = eval_filter(to, value, env) if to else [None]
                for tov in to_iter:
                    yield p + [{'start': frv, 'end': tov}]
        return
    if kind == 'optional':
        try:
            yield from eval_paths(node[1], value, env)
        except JqError:
            pass
        return
    if kind == 'if':
        _, cond, then, elifs, else_br = node
        for c in eval_filter(cond, value, env):
            if jq_truthy(c):
                yield from eval_paths(then, value, env)
            else:
                matched = False
                for ec, eb in elifs:
                    ok = False
                    for cc in eval_filter(ec, value, env):
                        if jq_truthy(cc):
                            ok = True
                            yield from eval_paths(eb, value, env)
                    if ok:
                        matched = True
                        break
                if not matched:
                    if else_br is not None:
                        yield from eval_paths(else_br, value, env)
                    else:
                        yield []
        return
    if kind == 'try':
        try:
            yield from eval_paths(node[1], value, env)
        except JqError:
            if node[2]:
                pass  # paths only come from left
        return
    if kind == 'alt':
        # // in path expr - paths of left (where result is non-null/false) else right
        had = False
        for p in eval_paths(node[1], value, env):
            v = resolve_path(value, p)
            if v is not None and v is not False:
                had = True
                yield p
        if not had:
            yield from eval_paths(node[2], value, env)
        return
    if kind == 'fcall':
        _, name, args = node
        # Check user-defined
        f = env.lookup_func(name, len(args))
        if f is not None:
            params, body, defenv = f
            new_env = bind_fcall_args(params, args, env, defenv)
            yield from eval_paths(body, value, new_env)
            return
        if name == 'recurse' and not args:
            yield from recurse_paths([], value)
            return
        if name == 'select' and len(args) == 1:
            for r in eval_filter(args[0], value, env):
                if jq_truthy(r):
                    yield []
            return
        # Some builtins produce paths identity
        # For others this is a path error
        raise JqError(f"Invalid path expression with result {jq_repr(value)}")
    raise JqError(f"Invalid path expression: {kind}")


def recurse_paths(prefix, v):
    yield list(prefix)
    if isinstance(v, list):
        for i, x in enumerate(v):
            yield from recurse_paths(prefix + [i], x)
    elif isinstance(v, dict):
        for k, x in v.items():
            yield from recurse_paths(prefix + [k], x)


def resolve_path(v, path):
    for p in path:
        if v is None: return None
        if isinstance(p, str):
            if isinstance(v, dict):
                v = v.get(p)
            else:
                raise JqError(f"Cannot index {jq_typeof(v)}")
        elif isinstance(p, int):
            if isinstance(v, list):
                if -len(v) <= p < len(v):
                    v = v[p]
                else:
                    v = None
            else:
                raise JqError(f"Cannot index {jq_typeof(v)}")
        elif isinstance(p, dict) and 'start' in p:
            v = get_slice(v, p['start'], p['end'])
    return v


def set_path(v, path, new_val):
    """Return a new copy of v with path set to new_val."""
    if not path:
        return new_val
    p = path[0]
    rest = path[1:]
    if isinstance(p, str):
        if v is None:
            v = {}
        if not isinstance(v, dict):
            raise JqError(f"Cannot update {jq_typeof(v)} with key")
        cur = v.get(p)
        new_sub = set_path(cur, rest, new_val)
        r = dict(v)
        r[p] = new_sub
        return r
    if isinstance(p, int):
        if v is None:
            v = []
        if not isinstance(v, list):
            raise JqError(f"Cannot update {jq_typeof(v)} with index")
        L = len(v)
        idx = p
        if idx < 0:
            idx += L
        if idx < 0:
            raise JqError("Out of range negative index")
        r = list(v)
        while len(r) <= idx:
            r.append(None)
        r[idx] = set_path(r[idx] if idx < L else None, rest, new_val)
        return r
    if isinstance(p, dict):
        fi = p.get('start'); ti = p.get('end')
        if v is None:
            v = []
        if not isinstance(v, list):
            raise JqError(f"Cannot slice {jq_typeof(v)}")
        L = len(v)
        fi2 = 0 if fi is None else int(_num(fi))
        ti2 = L if ti is None else int(_num(ti))
        if fi2 < 0: fi2 = max(0, L+fi2)
        if ti2 < 0: ti2 = max(0, L+ti2)
        fi2 = max(0, min(L, fi2))
        ti2 = max(0, min(L, ti2))
        slice_val = v[fi2:ti2]
        new_sub = set_path(slice_val, rest, new_val)
        if not isinstance(new_sub, list):
            raise JqError("slice must be replaced with an array")
        return v[:fi2] + new_sub + v[ti2:]
    raise JqError("bad path element")


def del_path(v, path):
    if not path:
        return None
    p = path[0]
    rest = path[1:]
    if isinstance(p, str):
        if v is None:
            return None
        if not isinstance(v, dict):
            raise JqError(f"Cannot delete from {jq_typeof(v)}")
        if p not in v:
            return v
        if not rest:
            r = dict(v)
            del r[p]
            return r
        r = dict(v)
        r[p] = del_path(r[p], rest)
        return r
    if isinstance(p, int):
        if v is None: return None
        if not isinstance(v, list):
            raise JqError("Cannot delete from non-array")
        L = len(v)
        idx = p
        if idx < 0: idx += L
        if idx < 0 or idx >= L:
            return v
        if not rest:
            return v[:idx] + v[idx+1:]
        r = list(v)
        r[idx] = del_path(r[idx], rest)
        return r
    if isinstance(p, dict):
        # slice delete
        if not rest:
            L = len(v)
            fi = p.get('start'); ti = p.get('end')
            fi2 = 0 if fi is None else int(_num(fi))
            ti2 = L if ti is None else int(_num(ti))
            if fi2 < 0: fi2 = max(0, L+fi2)
            if ti2 < 0: ti2 = max(0, L+ti2)
            fi2 = max(0, min(L, fi2))
            ti2 = max(0, min(L, ti2))
            return v[:fi2] + v[ti2:]
        # recurse inside slice - complex, skip
        return v
    return v


def eval_assign(op, path_expr, val_expr, value, env):
    if op == '=':
        # Get all the new values first; for each, set the paths
        for nv in eval_filter(val_expr, value, env):
            r = value
            for p in eval_paths(path_expr, value, env):
                r = set_path(r, p, nv)
            yield r
        return
    if op == '|=':
        # For each path, apply the update
        r = value
        for p in eval_paths(path_expr, value, env):
            cur = resolve_path(r, p)
            results = list(eval_filter(val_expr, cur, env))
            if not results:
                # delete
                r = del_path(r, p)
            else:
                r = set_path(r, p, results[0])
        yield r
        return
    op_map = {'+=':'+', '-=':'-', '*=':'*', '/=':'/', '%=':'%'}
    if op in op_map:
        bop = op_map[op]
        for nv in eval_filter(val_expr, value, env):
            r = value
            for p in eval_paths(path_expr, value, env):
                cur = resolve_path(r, p)
                new_val = apply_binop(bop, cur, nv)
                r = set_path(r, p, new_val)
            yield r
        return
    if op == '//=':
        r = value
        for p in eval_paths(path_expr, value, env):
            cur = resolve_path(r, p)
            if cur is not None and cur is not False:
                continue
            for nv in eval_filter(val_expr, value, env):
                r = set_path(r, p, nv)
                break
        yield r
        return
    raise JqError(f"unknown assignment {op}")


def bind_fcall_args(params, args, env, defenv):
    new_env = defenv.child()
    for (ptype, pname), a in zip(params, args):
        if ptype == 'filter':
            # bind as a thunk: key (name, 0) -> (params=[], body=a, env=caller_env)
            new_env.funcs[(pname, 0)] = ([], a, env)
        else:  # value
            # evaluate in caller env; if multiple values, jq would run once per; 
            # for simplicity do lazy single-value here - but that's wrong
            # Implement: collect first value. In practice, jq runs body once per combination.
            # We'll handle value params specially in eval_fcall.
            pass
    return new_env


def eval_fcall(name, args, value, env):
    # Check user-defined first
    f = env.lookup_func(name, len(args))
    if f is not None:
        params, body, defenv = f
        # Determine which params are value (need cross-product)
        value_params = [(i,p) for i,(pt,p) in enumerate(params) if pt == 'value']
        if not value_params:
            new_env = defenv.child()
            for (pt, pname), a in zip(params, args):
                new_env.funcs[(pname, 0)] = ([], a, env)
            yield from eval_filter(body, value, new_env)
            return
        # Cross-product over value params
        def rec(i, bindings):
            if i >= len(value_params):
                new_env = defenv.child()
                for (pt, pname), a in zip(params, args):
                    if pt == 'filter':
                        new_env.funcs[(pname, 0)] = ([], a, env)
                    else:
                        new_env.vars[pname] = bindings[pname]
                yield from eval_filter(body, value, new_env)
                return
            idx, pname = value_params[i]
            for v in eval_filter(args[idx], value, env):
                bindings[pname] = v
                yield from rec(i+1, bindings)
        yield from rec(0, {})
        return
    # Builtins
    from .jq_builtins import call_builtin
    yield from call_builtin(name, args, value, env)
