def _flags(f):
    r = 0
    if not f: return r
    if 'i' in f: r |= pyre.IGNORECASE
    if 'x' in f: r |= pyre.VERBOSE
    if 's' in f: r |= pyre.DOTALL
    if 'm' in f: r |= pyre.MULTILINE
    return r


def _match_obj(m, s):
    groups = []
    for i, g in enumerate(m.groups(), start=1):
        if g is None:
            groups.append({'offset': -1, 'length': 0, 'string': None, 'name': None})
        else:
            groups.append({
                'offset': m.start(i),
                'length': m.end(i) - m.start(i),
                'string': g,
                'name': None,
            })
    return {
        'offset': m.start(),
        'length': m.end() - m.start(),
        'string': m.group(0),
        'captures': groups,
    }


def _sub(pattern, repl_expr, value, env, flags, count):
    from .jq_eval import eval_filter, JqError
    if not isinstance(value, str):
        raise JqError("sub: string required")
    result = []
    last_end = 0
    matches_left = [count]
    def replace(m):
        if count and matches_left[0] <= 0:
            return m.group(0)
        matches_left[0] -= 1
        # Build binding of named captures
        # Eval repl_expr with the match as context
        local = value[m.start():m.end()]
        # jq allows interpolation with named captures only, but we'll evaluate
        # with current value
        results = list(eval_filter(repl_expr, value, env))
        if not results:
            return ''
        r = results[0]
        if not isinstance(r, str):
            r = format_value(r, indent=0)
        return r
    return pyre.sub(pattern, replace, value, count=(count if count else 0), flags=flags)


def _walk(v, f, env):
    from .jq_eval import eval_filter
    if isinstance(v, list):
        v = [_walk(x, f, env) for x in v]
    elif isinstance(v, dict):
        v = {k: _walk(x, f, env) for k, x in v.items()}
    for r in eval_filter(f, v, env):
        return r
    return v


def _flatten(arr, depth):
    out = []
    for x in arr:
        if isinstance(x, list) and depth > 0:
            out.extend(_flatten(x, depth-1))
        else:
            out.append(x)
    return out


def recurse_all(v):
    yield v
    if isinstance(v, list):
        for x in v:
            yield from recurse_all(x)
    elif isinstance(v, dict):
        for x in v.values():
            yield from recurse_all(x)


def _recurse_with(v, f, env):
    from .jq_eval import eval_filter
    yield v
    for nv in eval_filter(f, v, env):
        yield from _recurse_with(nv, f, env)


def builtin_length(v):
    if v is None: return 0
    if isinstance(v, bool):
        from .jq_eval import JqError
        raise JqError("boolean has no length")
    if isinstance(v, str): return len(v)
    if isinstance(v, list): return len(v)
    if isinstance(v, dict): return len(v)
    if isinstance(v, (int, float, JsonNumber)):
        return abs(_num(v))
    from .jq_eval import JqError
    raise JqError("no length")


def builtin_keys(v, sort=True):
    if isinstance(v, dict):
        keys = list(v.keys())
        if sort: keys.sort()
        return keys
    if isinstance(v, list):
        return list(range(len(v)))
    from .jq_eval import JqError
    raise JqError(f"{repr(v)} has no keys")


_TYPE_ORDER = {'null':0, 'false':1, 'true':2, 'number':3, 'string':4, 'array':5, 'object':6}

class SortKey:
    __slots__ = ('v',)
    def __init__(self, v): self.v = v
