            except (IOError, JsonParseError) as e:
                sys.stderr.write(f"jq: error reading slurpfile: {e}\n")
                return 2
            i += 2
        elif a == '--rawfile':
            if i + 2 >= len(argv):
                sys.stderr.write("jq: --rawfile requires name and file\n")
                return 2
            try:
                with open(argv[i+2], 'r') as fp:
                    opts.named_args[argv[i+1]] = fp.read()
            except IOError as e:
                sys.stderr.write(f"jq: error reading rawfile: {e}\n")
                return 2
            i += 2
        elif a == '--args':
            opts.args_mode = 'args'
        elif a == '--jsonargs':
            opts.args_mode = 'jsonargs'
        elif a.startswith('-') and len(a) > 1 and a[1] != '-':
            # Short option bundle like -cr or -nr
            rest = a[1:]
            extra = []
            for ch in rest:
                extra.append('-' + ch)
