    opts.filter = filter_src

    return run(opts)


def run(opts):
    try:
        ast = parse(opts.filter)
    except (ParseError, LexError) as e:
        name = "<top-level>"
        sys.stderr.write(f"jq: error: {e}\njq: 1 compile error\n")
        return 3

    env = Env()
    # Set named args as variables
    for k, v in opts.named_args.items():
        env.vars[k] = v

    # $ENV, $__loc__, $ARGS
    import os
    env.vars['ENV'] = dict(os.environ)
    env.vars['__loc__'] = {'file': '<top-level>', 'line': 1}
    env.vars['ARGS'] = {
        'positional': opts.positional_args,
        'named': dict(opts.named_args),
    }

    # Stream of inputs
    def read_inputs():
        if opts.input_files:
            for fname in opts.input_files:
                try:
                    with open(fname, 'r') as fp:
                        data = fp.read()
                except IOError as e:
                    sys.stderr.write(f"jq: error: Could not open file {fname}: {e}\n")
                    continue
                if opts.raw_input:
                    if opts.slurp:
                        yield data
                    else:
                        for line in data.splitlines():
                            yield line
                else:
                    try:
                        for v in parse_stream(data):
                            yield v
                    except JsonParseError as e:
                        sys.stderr.write(f"jq: parse error: {e}\n")
                        raise SystemExit(2)
        else:
            data = sys.stdin.read()
            if opts.raw_input:
                if opts.slurp:
                    yield data
                else:
                    for line in data.splitlines():
                        yield line
