                    raise SystemExit(2)

    # Determine input list
    if opts.null_input:
        inputs = [None]
    elif opts.slurp:
        if opts.raw_input:
            # concat all strings
            data = []
            for v in read_inputs():
                data.append(v)
            inputs = [''.join(data)] if opts.raw_input else [data]
            # Actually with -Rs it's single concatenated string
            inputs = [''.join(data)]
        else:
            inputs = [list(read_inputs())]
    else:
        inputs = None  # stream

    had_output = False
    any_true = False

    indent = 0 if opts.compact else opts.indent

    def emit(v):
        nonlocal had_output, any_true
        had_output = True
        if v is not None and v is not False:
            any_true = True
        if opts.raw_output and isinstance(v, str):
            sys.stdout.write(v)
            if opts.raw_output0:
                sys.stdout.write('\0')
            elif opts.join_output:
                pass
            else:
                sys.stdout.write('\n')
        else:
            s = format_value(v, indent=indent, sort_keys=opts.sort_keys,
                           ascii_only=opts.ascii, tab=opts.tab)
            sys.stdout.write(s)
            if opts.join_output:
                pass
            else:
                sys.stdout.write('\n')
        if opts.unbuffered:
            sys.stdout.flush()

    try:
        if inputs is not None:
            for inp in inputs:
                for v in eval_filter(ast, inp, env):
                    emit(v)
        else:
            for inp in read_inputs():
                for v in eval_filter(ast, inp, env):
                    emit(v)
    except JqError as e:
        sys.stderr.write(f"jq: error (at <unknown>): {e}\n")
        return 5
    except BrokenPipeError:
        return 0

    if opts.exit_status:
        if not had_output:
            return 1
        if not any_true:
            return 1
    return 0


