    def to_stream_events(v, path=None):
        if path is None:
            path = []
        if isinstance(v, list):
            if not v:
                yield [list(path), []]
            else:
                for i, x in enumerate(v):
                    yield from to_stream_events(x, path + [i])
                yield [list(path) + [len(v) - 1]]
        elif isinstance(v, dict):
            if not v:
                yield [list(path), {}]
            else:
                keys = list(v.keys())
                for k in keys:
                    yield from to_stream_events(v[k], path + [k])
                yield [list(path) + [keys[-1]]]
        else:
            yield [list(path), v]
    def streamed():
        for v in base_iter:
            yield from to_stream_events(v)
    input_iter = streamed() if opts.stream else base_iter'''
s = s.replace(old, new)
with open('src/main.py','w') as f:
    f.write(s)
print("done")
